import json,numpy as np
from pathlib import Path
R=json.loads(Path('fixed_results.json').read_text())
P=Path('models');P.mkdir(exist_ok=True)
def param(name,value,unit,typ,description,equation=None):
 p={'name':name,'value':float(value),'unit':unit,'type':typ,'description':description}
 if equation:p['equation']=equation
 return p
v='(Min(Max(valve,0),vfull)/vfull)'
shape=f'(weight*(1-{v}**3)+(1-weight)*(1-3*{v}**2+2*{v}**3))'
g=f'(gopen*{shape})';z='Max(p-patm,0)'
common_fixed=[param('patm',1,'bar','fixed','Atmospheric reference pressure, `patm = 1` bar, supplied approximately by TASK.md and here assumed exactly; not adjusted to reduce simulation errors.'),param('vfull',100,'%','fixed','Fully closed valve normalization, `vfull = 100` %, from TASK.md. Clamping `Min(Max(valve,0),vfull)` restricts the conductance extension to the physical stroke.'),param('back',.1,'1/s','fixed','Subatmospheric restoring rate, `back = 0.1` 1/s, chosen as a ten-second numerical vacuum-relaxation time, not estimated. `-back*Min(p-patm,0)` is a valve-independent extension outside normal pressurized operation, not an identified leak or a model of real reverse valve flow.')]
for r in R['pooled']:
 label=r['label'];fam=r['family'];x=r['final_x'];a=x[0];w=x[3]
 pars=[param('ain',a,'bar/(s*(l/min))','fitted','Effective inlet conversion coefficient: `ain*flow` adds pressure from metered air. Estimated jointly with the other independent coefficients at both fitting stages described below.'),param('weight',w,'-','fitted','Fraction of open-valve conductance assigned to `1-(valve/vfull)**3`; the complement multiplies `1-3*(valve/vfull)**2+2*(valve/vfull)**3`. Both basis functions decrease with closure and vanish at the seat. Estimated jointly at both stages.')]
 if fam==4:
  gopen=x[1];rv=x[2]
  pars += [param('gopen',gopen,'sqrt(bar)/s','fitted','Open-valve inertial conductance scale. Estimated jointly at both stages; no valve area or discharge coefficient is separately identifiable.'),param('rvisc',rv,'s','fitted','Series linear pneumatic resistance converting pressure-rate discharge to pressure loss. Estimated jointly at both stages subject to `2 <= rvisc <= 30` s; the fitted value reaches the lower bound, so only a weakly determined low-pressure resistance is claimed.'),param('tiny',1e-12,'bar','fixed','Denominator safeguard, `tiny = 1e-12` bar, chosen solely to avoid a zero denominator at the fully closed seat and atmospheric pressure; negligible over measured pressure differences.')]
  expression=f'ain*flow-{g}*2*{z}/(sqrt(4*{z}+(rvisc*{g})**2+tiny)+rvisc*{g})-back*Min(p-patm,0)'
  family='Lumped isothermal ideal-gas inventory balance with a linear-plus-quadratic (Darcy–Forchheimer-type) series outlet resistance. The linear-plus-quadratic loss analogy, not a literal porous medium, motivates the resistance law; no particular publication was used for this structure.'
  interp=f'Pressure `p` is absolute pressure. The term `ain*flow` is the inlet contribution for an approximately isothermal gas inventory of fixed effective volume. Define the nonnegative overpressure `z = Max(p-patm,0)` bar and the valve conductance `g = {g}` in sqrt(bar)/s, with `weight` its monotone-basis fraction. If `u` is outlet discharge expressed as a pressure rate in bar/s, the assumed loss is `z = rvisc*u+(u/g)**2`; solving its positive root gives the implemented term `{g}*2*{z}/(sqrt(4*{z}+(rvisc*{g})**2+tiny)+rvisc*{g})`. This combines viscous resistance in the outlet piping with a valve-dependent inertial restriction; the assignment to individual hardware is not identifiable. The safeguard `tiny` has no physical meaning. At the fully closed seat the implemented outlet rate is exactly zero. The final term `-back*Min(p-patm,0)` restores numerical undershoots only; it is not reverse-flow physics.'
  origin='Started with linear relaxation, square-root discharge, compressible nozzle flow, positive pressure-power laws and power/exponential valve characteristics. Initial transition fits showed that near-square-root discharge substantially improved on linear pressure relaxation. Residuals by low pressure and valve opening motivated adding a series linear resistance instead of an arbitrary derivative offset: an offset would break zero-flow equilibrium. The linear-plus-quadratic pressure-drop structure came from physical reasoning, not symbolic search. The two monotone cubic valve basis functions are a deliberately parsimonious empirical stroke map. A third positive cubic basis coefficient converged essentially to zero in the exploratory fits and was removed. All coefficients in the delivered expression were then refitted, not copied from that exploratory fit.'
  units=['bar/(s*(l/min))','sqrt(bar)/s','s','']
  btext='`0.0001 <= ain <= 0.005` bar/(s*(l/min)), `0.0001 <= gopen <= 0.4` sqrt(bar)/s, `2 <= rvisc <= 30` s and `0 <= weight <= 1`. Positive broad gain bounds avoid unphysical signs; the resistance lower bound limits the continuous restoring slope to at most `0.5` 1/s, avoiding an unresolved sub-sample outlet time scale in five-second RK4. The upper resistance bound allows slow, strongly viscous behavior.'
  names=['ain','gopen','rvisc','weight']
 else:
  cap=x[1];eps=x[2];gopen=r['parameters'][1]+r['parameters'][2]
  pars += [param('cap',cap,'1/s','fitted','Maximum small-overpressure relaxation-rate scale at the open valve. Estimated jointly with the other independent coefficients, with `0.03 <= cap <= 0.5` 1/s to make the near-atmospheric dynamics resolvable by one five-second RK4 step.'),param('eps',eps,'bar','fitted','Pressure scale for smoothing the ideal square-root cusp near atmosphere. Estimated jointly at both stages, with `0.01 <= eps <= 0.5` bar; this is an effective laminar/low-Reynolds-number crossover correction, not independently measured hardware.')]
  if fam==1:
   pars += [param('gopen',gopen,'sqrt(bar)/s','tied','Open-valve conductance, tied to the fitted slope and crossover scale so the restoring slope is bounded without an additional penalty in the pressure-fitting criterion.','cap*sqrt(eps)')]
   hout=f'{z}/({z}**2+eps**2)**0.25';expression=f'ain*flow-{g}*{hout}-back*Min(p-patm,0)'
   family='Lumped isothermal ideal-gas inventory balance with a regularized Bernoulli/orifice discharge law. Bernoulli discharge supplies the square-root pressure-drop asymptote; the analytic cusp smoothing and monotone cubic valve map are empirical additions, not claimed to follow exactly from Bernoulli’s equation.'
   interp=f'Define `z = Max(p-patm,0)` bar and `g = {g}` in sqrt(bar)/s. The term `ain*flow` is the effective ideal-gas inlet contribution. The outlet contribution `{g}*{hout}` is nonnegative, asymptotes to `g*sqrt(z)` at overpressures large compared with `eps`, and is approximately `g*z/sqrt(eps)` near atmosphere. This smoothly represents a low-pressure linear regime rather than an ideal orifice cusp. The tie `gopen = cap*sqrt(eps)` makes the largest outlet restoring slope equal to `cap` at an open valve and atmosphere. `weight` controls the monotone valve stroke curve; it is not a physical valve area. The term `-back*Min(p-patm,0)` is a valve-independent numerical vacuum extension outside the fitted pressure regime, not a leak.'
   origin='The inlet term and square-root pressure dependence came from a fixed-volume isothermal mass balance and Bernoulli/orifice reasoning. Linear discharge gave substantially biased high-pressure simulations, and unconstrained pressure-power fits favored an exponent close to one half. The ideal square root is non-Lipschitz at atmosphere; exploratory near-zero smoothing scales produced excessive slopes for a five-second numerical step. Therefore the delivered family uses positive fitted smoothing with an explicit fitted restoring-slope bound. This regularization is a modeling choice, not a discovered physical law. The valve map was an empirical monotone cubic choice; a third positive basis coefficient was essentially zero and removed after exploratory fitting. Exponential and power-opening maps were also tried but did not give a compelling validation improvement. No genetic symbolic-regression search supplied this expression.'
  else:
   gamma=1.4;crit=(2/(gamma+1))**(gamma/(gamma-1));ratio='Max(patm/Max(p,patm),rcrit)'
   pars += [param('gamma',gamma,'-','fixed','Ideal-air ratio of specific heats, `gamma = 1.4`, assumed for room-temperature air; not fitted. NASA Glenn Research Center, Mass Flow Choking, supplies the ideal-air nozzle framework (source checked during this round).'),param('rcrit',crit,'-','tied','Critical downstream/upstream pressure ratio for an isentropic converging nozzle; below this ratio the ideal mass flux is choked.','(2/(gamma+1))**(gamma/(gamma-1))'),param('gopen',gopen,'bar/s','tied','Open-valve scale of the dimensionless compressible mass-flux function, tied to the fitted near-atmospheric rate and crossover pressure.','cap*sqrt(eps*patm/2)')]
   hout=f'(Max(p,patm)/patm)*sqrt(Max(2*gamma/(gamma-1)*({ratio}**(2/gamma)-{ratio}**((gamma+1)/gamma)),0))*sqrt({z}/sqrt({z}**2+eps**2))'
   expression=f'ain*flow-{g}*{hout}-back*Min(p-patm,0)'
   family='Lumped isothermal gas-inventory balance with regularized isentropic compressible nozzle discharge, including sonic choking. Reference: NASA Glenn Research Center, Mass Flow Choking (online source checked during this round). The nozzle law describes discharge, while isothermal storage describes the tank; these are distinct assumptions.'
   interp=f'Define `z = Max(p-patm,0)` bar, `pu = Max(p,patm)` bar, `ratio = {ratio}`, and `g = {g}` bar/s. The term `ain*flow` supplies pressure from the metered inlet. The term `{g}*{hout}` removes gas through an ideal isentropic restriction; `gamma` is the assumed ideal-air heat-capacity ratio, and `rcrit` prevents the pressure ratio from dropping below the sonic critical value. The factor `sqrt(z/sqrt(z**2+eps**2))` smooths the nozzle cusp at atmosphere and tends to unity well above `eps`. The tie `gopen = cap*sqrt(eps*patm/2)` sets the limiting small-overpressure restoring slope to `cap`. The heat-capacity assumption and choking transition come from gas physics, whereas the smoothing and `weight` stroke map are empirical. `-back*Min(p-patm,0)` restores numerical undershoots independently of valve position; it is not a real reverse-flow model.'
   origin='A compressible outlet law was included because observed absolute pressure extends above twice atmospheric pressure, where an ideal-air restriction can approach choking. Its pressure-ratio powers and critical-ratio clamp came from isentropic nozzle theory, rather than an algebraic search. Simple incompressible square-root and linear families were tried first. Unregularized nozzle simulations have a cusp at atmosphere; a pressure crossover scale and a bounded near-atmospheric slope were added for stable five-second integration. The two positive monotone cubic valve basis functions are empirical, and a third basis coefficient was removed after exploratory fits made it negligible. No symbolic search was used to generate the nozzle expression.'
  units=['bar/(s*(l/min))','1/s','bar',''];names=['ain','cap','eps','weight']
  btext='`0.0001 <= ain <= 0.005` bar/(s*(l/min)), `0.03 <= cap <= 0.5` 1/s, `0.01 <= eps <= 0.5` bar and `0 <= weight <= 1`. The gain is broadly positive, the crossover stays nonsingular, the weights enforce a monotone valve map, and the rate ceiling avoids an unresolved atmospheric-pressure cusp during a five-second RK4 step.'
 pars+=common_fixed
 def vals(xx):return ', '.join(f'`{n} = {val:.12g}`'+(' '+unit if unit else '') for n,val,unit in zip(names,xx,units))
 method=f'Bound-constrained nonlinear least squares using the Trust Region Reflective algorithm in scipy.optimize.least_squares (SciPy 1.18.1). Reference: SciPy official least_squares documentation, checked in this round. Nonlinearity and physical bounds make a direct linear solution inapplicable. All four independent parameters were estimated together in each of two stages. First minimize squared one-step RK4 pressure-transition errors, starting at {vals(r["initial"])}; these broad positive guesses are close to preliminary mass-balance fit scales and avoid a vanishing-conductance start. That stage yielded {vals(r["transition_x"])}. Then, starting at those values, minimize squared full free-run pressure errors and obtain {vals(x)}. The numerical bounds were {btext} Both stages use two-point finite-difference Jacobians, `x_scale = "jac"`, linear loss, and relative stopping settings `ftol = 1e-11`, `xtol = 1e-11`, `gtol = 1e-11`; maximum function evaluations were 1000 and 1500 respectively, with actual solver counts {r["nfev"][0]} and {r["nfev"][1]}. Each simulation is one classical RK4 step per `Ts = 5` s with the current logged inputs held constant. Numba 0.68.0 compiles the loops; no random sampling or seeds apply. Fixed and tied parameters are not optimization variables. The function guards excursions beyond 20 bar with a finite penalty; neither final fitted training trajectory approaches that guard.'
 tr=next(y for y in R['train'] if y['label']==label);bl=next(y for y in R['blocked'] if y['label']==label)
 limitations=f'The effective inlet volume, valve area, discharge coefficient, temperature, bubble holdup and calibration cannot be separated from these two pressure/input trajectories. No flow-delay, thermal or actuator state is present. On an independently simulated validation trajectory, the earlier training-only fit gave RMSE {tr["metrics"]["val"]["rmse"]:.6f} bar; first-two-thirds fits gave fresh-initialized tail RMSE {bl["heldout_tail"]["train"]:.6f} bar on training and {bl["heldout_tail"]["val"]:.6f} bar on validation. Final all-data refitting gave training RMSE {r["metrics"]["train"]["rmse"]:.6f} bar and validation RMSE {r["metrics"]["val"]["rmse"]:.6f} bar; these last two are fitting diagnostics, not independent validation. Final one-step residual correlations with the next-minus-current inlet-flow change are {r["metrics"]["train"]["corr_flow_change"]:.3f} on training and {r["metrics"]["val"]["corr_flow_change"]:.3f} on validation, showing missing timing/dynamics that the autonomous single-state form cannot resolve. Alternative future-flow diagnostic fits reduced transition errors but were excluded because future inputs are not arguments. The fully open and sealed endpoints are extrapolated: training stroke spans approximately 10.31 to 92.41 %, validation 1.63 to 94.45 %. The subatmospheric term has no identified physical validity. Absolute pressures far outside the observed approximately 0.99 to 2.19 bar range, thermal transients, liquid-level changes and negative inlet flows are not validated. '
 if fam==4:limitations+='The resistance `rvisc` reaches its 2 s bound; its estimate is partly determined by the chosen time-resolution safeguard, not a resolved pipe measurement. '
 else:limitations+='The fitted crossover scale is not small compared with typical overpressures, so the regularization materially affects the result and must not be represented as a harmless numerical epsilon. '
 requirements='R1: `ain > 0`, so increasing `flow` always increases `dp`. R2: for `0 <= weight <= 1`, both cubic stroke basis functions are nonincreasing in closure, the pressure-drop discharge is nonnegative, and the subatmospheric term does not depend on closure; hence increasing `valve` cannot decrease `dp`, including in the implemented vacuum extension. R3: at `flow = 0` and `p = patm`, all terms vanish, with `patm = 1` bar. R4: for any not-fully-closed valve and `flow = 0`, `dp < 0` above `patm` and `dp > 0` below it, so atmospheric equilibrium is attractive. R5: at `valve = vfull`, the conductance is exactly zero, so for `flow >= 0` the derivative `ain*flow-back*Min(p-patm,0)` is nonnegative. No unexplained outlet leak remains at the sealed seat. These are structural properties, not conclusions inferred just from observed samples.'
 limitations+=requirements
 candidate={'expressions':{'dp':expression},'parameters':pars,'estimation':{'criterion':'Final criterion: sum of squared free-run errors on pressure `p` in bar after each trajectory’s first sample, with no state correction. This matches long-horizon evaluation and avoids treating the filtered derivative `dp` as an independent instantaneous measurement. One-step pressure-transition squared error is only an initialization criterion.','data':'Final coefficients use all 1452 rows of data/train.csv and all 1454 rows of data/val.csv as two separate trajectories, without joining their endpoints. There are 1451 and 1453 fitted pressure transitions. Initial samples set each free-run initial condition and are not residuals. The derivative column `dp` is not used for final estimation. The independent training-only comparison and first-two-thirds blocked comparison in fixed_atmosphere.py were used to assess structure generalization; only after these checks were both entire trajectories used to improve coefficient coverage. No rows were removed for outlier or transient handling and no test data were accessed.','method':method,'script':'fixed_atmosphere.py'},'discussion':{'family':family,'interpretation':interp,'origin':origin,'limitations':limitations}}
 (P/(label+'.json')).write_text(json.dumps(candidate,indent=2))
reason='Recommend mixed: it has the lowest training-only independent validation RMSE among the final fixed-atmosphere families (0.038665 bar) and the lowest pooled fit RMSE on validation (0.037484 bar, not independent). Its series viscous/inertial pressure-loss model gives a finite, bounded atmospheric restoring slope and an exactly sealed seat without a large ad hoc pressure smoothing scale. The fresh-initialized blocked-tail checks show similar rather than decisive differences between nonlinear families and appreciable experiment drift; no test-performance guarantee is claimed. Bernoulli and choked-nozzle candidates are retained as physically distinct discharge assumptions, not coefficient variants. All three explicitly meet R1–R5 over the physical inlet/stroke domain and use current inputs only.'
(P/'pool.json').write_text(json.dumps({'order':['mixed','bernoulli','choked'],'recommended':'mixed','reason':reason},indent=2))
print('Wrote three candidates and pool.')
